  // If you say 'typedef Foo Bar', then clients can use Bar however
  // they want without having to worry about #including anything
  // except you.  That puts you on the hook for all the #includes that
  // Bar might need, for *anything* one might want to do to a Bar.
  // TODO(csilvers): we can probably relax this rule in .cc files.
  // TODO(csilvers): this should really move into IwyuBaseASTVisitor
  // (that way we'll correctly identify need for hash<> in hash_set).
  // This is called from Traverse*() because Visit*()
  // can't call HandleFunctionCall().
  bool HandleAliasedClassMethods(TypedefNameDecl* decl) {
    if (CanIgnoreCurrentASTNode())
      return true;

    const Type* underlying_type = decl->getUnderlyingType().getTypePtr();
    if (!AllTypesProvided(underlying_type, current_ast_node()->GetLocation()))
      return true;
    const Decl* underlying_decl = TypeToDeclAsWritten(underlying_type);

    // We simulate a user calling all the methods in a class.
    if (const CXXRecordDecl* record_decl = DynCastFrom(underlying_decl)) {
      for (DeclContext::decl_iterator it = record_decl->decls_begin();
           it != record_decl->decls_end(); ++it) {
        FunctionDecl* fn_decl = nullptr;
        if (CXXMethodDecl* method_decl = DynCastFrom(*it)) {
          fn_decl = method_decl;
        } else if (FunctionTemplateDecl* tpl_decl = DynCastFrom(*it)) {
          fn_decl = tpl_decl->getTemplatedDecl();   // templated method decl
        } else {
          continue;    // not a method or static method
        }
        if (!this->getDerived().HandleFunctionCall(
                fn_decl, underlying_type, static_cast<Expr*>(nullptr)))
          return false;
      }
    }
    // We don't have to simulate a user instantiating the type, because
    // RecursiveASTVisitor.h will recurse on the typedef'ed type for us.
    return true;
  }

  bool TraverseTypedefDecl(TypedefDecl* decl) {
    if (!Base::TraverseTypedefDecl(decl))
      return false;

    return HandleAliasedClassMethods(decl);
  }

  bool TraverseTypeAliasDecl(TypeAliasDecl* decl) {
    if (!Base::TraverseTypeAliasDecl(decl))
      return false;

    return HandleAliasedClassMethods(decl);
  }

  bool VisitFunctionDecl(FunctionDecl* decl) {
    if (CanIgnoreCurrentASTNode())
      return true;
    // If a function declaration specifies default arguments but not for
    // the last parameters, like this:
    // void Fn(int = 0, int);
    // there should be (a) prior declaration(s) that specifies default argument
    // values for the last parameters.
    for (unsigned i = 1, ie = decl->getNumParams(); i < ie; ++i) {
      if (IsDefArgSpecified(i - 1, decl) && !IsDefArgSpecified(i, decl)) {
        // There should be a fn redecl specifying the i-th param default value.
        for (const FunctionDecl* redecl : decl->redecls()) {
          if (IsDefArgSpecified(i, redecl)) {
            ReportDeclUse(CurrentLoc(), redecl, nullptr, UF_RedeclUse);
            return Base::VisitFunctionDecl(decl);
          }
        }
      }
    }
    return Base::VisitFunctionDecl(decl);
  }

  // Avoid forward-declaration warnings for types which _should_ be already
  // provided by the primary method declaration. For example,
  // for 'struct Derived : public Base { T1 method(const T2&); };', T1 and T2
  // are provided by Base, and should not be forward-decl reported in Derived.
  bool TraverseCXXMethodDecl(CXXMethodDecl* method_decl) {
    if (CanIgnoreCurrentASTNode())
      return true;

    if (!method_decl->size_overridden_methods())
      return Base::TraverseCXXMethodDecl(method_decl);

    set<const Decl*> fwd_blocked = blocked_for_fwd_decl_;
    auto add_canonical_components = [&fwd_blocked](QualType part) {
      for (const Type* type : GetCanonicalComponentsOfType(part.getTypePtr())) {
        if (const Decl* decl = TypeToDeclAsWritten(type)) {
          // For templates, retrieve primary template declaration so as to match
          // what VisitTemplateSpecializationType does.
          if (const auto* spc = dyn_cast<ClassTemplateSpecializationDecl>(decl))
            decl = spc->getSpecializedTemplate();
          fwd_blocked.insert(decl->getCanonicalDecl());
        }
      }
    };
    add_canonical_components(method_decl->getReturnType());
    for (const ParmVarDecl* param : method_decl->parameters())
      add_canonical_components(param->getType());

    ValueSaver<set<const Decl*>> blocked_fwd_decl_guard =
        ScopedAdditionalBlockedForFwdDecl(fwd_blocked);
    // Full type info suggestions are blocked in CanBeProvidedTypeComponent.
    return Base::TraverseCXXMethodDecl(method_decl);
  }

  bool VisitRedeclarableTemplateDecl(RedeclarableTemplateDecl* decl) {
    if (CanIgnoreCurrentASTNode())
      return true;
    // Similar to default function args, default template args require redecls
    // specifying the last ones to be present. This is true for class templates,
    // variable templates, alias templates, but not for function templates.
    if (isa<FunctionTemplateDecl>(decl))
      return Base::VisitRedeclarableTemplateDecl(decl);
    const TemplateParameterList* params = decl->getTemplateParameters();
    for (unsigned i = 1, ie = params->size(); i < ie; ++i) {
      if (IsDefTplArgInherited(params->getParam(i)) &&
          IsDefTplArgSpecified(params->getParam(i - 1))) {
        // Find the redeclaration specifying default arg for the i-th parameter.
        for (const RedeclarableTemplateDecl* redecl : decl->redecls()) {
          const TemplateParameterList* redecl_params =
              redecl->getTemplateParameters();
          if (IsDefTplArgSpecified(redecl_params->getParam(i))) {
            ReportDeclUse(CurrentLoc(), redecl, nullptr, UF_RedeclUse);
            return Base::VisitRedeclarableTemplateDecl(decl);
          }
        }
      }
    }
    return Base::VisitRedeclarableTemplateDecl(decl);
  }

