  // --- Visitors of types derived from Type.

  // Avoid reporting any type sugar in an implicit code. It is assumed that
  // TraverseType isn't called for explicitly written types. TraverseTypeLoc
  // uses an additional check.
  bool TraverseType(QualType type, bool /*traverse_qualifier*/ = true) {
    if (type.isNull())
      return true;
    const Type* desugared = Desugar(type.getTypePtr());
    // Type prefixes should be handled only where explicitly written.
    return Base::TraverseType(QualType{desugared, 0}, false);
  }

  bool TraverseTypeLoc(TypeLoc typeloc, bool traverse_qualifier = true) {
    if (typeloc.isNull())
      return true;
    if (InImplicitCode(current_ast_node())) {
      const Type* desugared = Desugar(typeloc.getTypePtr());
      // Type prefixes should be handled only where explicitly written.
      return Base::TraverseType(QualType{desugared, 0}, false);
    }
    return Base::TraverseTypeLoc(typeloc, traverse_qualifier);
  }

  bool VisitTypedefType(TypedefType* type) {
    if (CanIgnoreCurrentASTNode())
      return true;
    // TypedefType::getDecl() returns the place where the typedef is defined.
    if (!InImplicitCode(current_ast_node()))
      ReportDeclUse(CurrentLoc(), type->getDecl());
    return Base::VisitTypedefType(type);
  }

  bool VisitUsingType(UsingType* type) {
    if (CanIgnoreCurrentASTNode())
      return true;

    if (CanForwardDeclareType(current_ast_node())) {
      ReportDeclForwardDeclareUse(CurrentLoc(), type->getDecl());
    } else {
      ReportDeclUse(CurrentLoc(), type->getDecl());

      // If UsingType refers to a typedef, report the underlying type of that
      // typedef if needed (which is determined in ReportTypeUse).
      const Type* underlying_type = type->desugar().getTypePtr();
      if (isa<TypedefType>(underlying_type)) {
        ReportTypeUse(CurrentLoc(), underlying_type, DerefKind::None);
      } else if (IsTemplatizedType(underlying_type)) {
        TemplateInstantiationData data = GetTplInstData(underlying_type);
        // TODO(bolshakov): add tests on the next line (if it actually works).
        InsertAllInto(GetProvidedTypeComponents(type), &data.provided_types);
        instantiated_template_visitor_.ScanInstantiatedType(
            current_ast_node(), data.resugar_map, data.provided_types);
      }
    }

    return Base::VisitUsingType(type);
  }

  // This is a superclass of RecordType and CXXRecordType.
  bool VisitTagType(TagType* type) {
    if (CanIgnoreCurrentASTNode())
      return true;

    const auto [is_provided, comment] =
        IsProvidedTypeComponent(current_ast_node());
    // If we're forward-declarable, then no complicated checking is
    // needed: just forward-declare.
    if (CanForwardDeclareType(current_ast_node()) && !is_provided) {
