  }

  bool VisitTagTypeLoc(TagTypeLoc type_loc) {
    if (type_loc.getTypePtr()->getKeyword() != ElaboratedTypeKeyword::None) {
      preprocessor_info()
          .FileInfoFor(CurrentFileEntry())
          ->AddOwningTagType(type_loc);
    }
    return Base::VisitTagTypeLoc(type_loc);
  }

